export const algorithmConcepts=[
lesson(29,'ResNet','RESIDUAL NETWORK',0,'学习“修正量”，把网络搭得更深。','残差块将变换分支与快捷支路相加。它让模型能够学习对已有表示的修正。',['拖动分支系数，比较普通堆叠与残差堆叠。','线性化微实验中，每层分支为 ax，快捷支路为 x。','真实 ResNet 还包含卷积、归一化与非线性。'],'普通: y=aᴸx; 残差: y=(1+a)ᴸx',[['a','分支系数 a',-.5,.5,.05,.1],['depth','堆叠层数',1,8,1,4]],['分支 F(x)=0 时，残差块保留什么？',['保留输入 x','全部变成 0'],0,'快捷支路让 y=x+F(x)=x。'], 'https://arxiv.org/abs/1512.03385',{
file:'resnet',paper:'Deep Residual Learning for Image Recognition',input:'图像张量 [B,C,H,W] 与类别标签。',output:'每张图的类别 logits；也可以作为视觉骨干输出特征。',objective:'图像分类通常优化交叉熵；残差连接改变网络结构，不额外定义一种分类损失。',training:['划分训练与验证图像，训练集做增强。','图像经卷积进入残差块，匹配相加张量的形状。','得到类别 logits，计算交叉熵。','反向传播并更新卷积、归一化等参数。','关闭训练模式，用独立数据计算分类指标。'],evaluation:'区分训练/推理模式；比较模型时匹配数据、增强、计算预算。',boundary:'动画只比较线性化堆叠。代码为单残差块的合成图像分类，省略完整 ResNet 深度与训练配方。',reading:['先明确退化问题与过拟合的区别。','对照残差块结构，找出 identity shortcut 与投影支路。','阅读不同深度与快捷连接的实验，检查对照条件。']}),
lesson(30,'Vision Transformer','VISION TRANSFORMER · ViT',0,'把图像切成小块，再用注意力连接。','ViT 将图像块当作 token，加入位置信息后，用 Transformer 组合全局信息。',['改变 patch 边长，看 token 数如何改变。','图像固定为 8×8，patch 必须整除图像边长。','注意力配对数量按 token 数的平方增长；并非总运行时间。'],'N=(H/P)(W/P); patch vector size=P²C',[['patch','Patch 边长',[ '2','4'],'2']],['patch 更小时，token 数通常怎样变化？',['更多','更少'],0,'同一幅图被切成更多小块，序列更长。'],'https://arxiv.org/abs/2010.11929',{
file:'vit',paper:'An Image is Worth 16x16 Words: Transformers for Image Recognition at Scale',input:'固定大小图像与分类标签。',output:'图像类别预测或图像表示。',objective:'对图像级类别预测计算交叉熵，梯度传回 patch 投影、注意力与分类头。',training:['把图像按不重叠 patch 切分并线性投影。','加入位置嵌入，组成 token 序列。','经自注意力和前馈层组合信息。','汇聚 token，计算分类损失并反向传播。','固定分辨率与预处理，在独立图像上评估。'],evaluation:'patch 大小、分辨率与预训练数据都会影响比较；小样本玩具实验不能验证大规模表现。',boundary:'代码使用小型 Transformer 与平均池化；不下载预训练权重，也不复现论文的大规模预训练。',reading:['从 patch embedding 到分类头画出张量形状。','比较局部卷积先验与全局 token 交互。','检查预训练数据规模和迁移设置，再解读结果。']}),
lesson(31,'Transformer','TRANSFORMER',1,'用注意力与位置编码组织上下文。','Transformer 用注意力建立 token 间的依赖。原始模型包含编码器与解码器，不能只把它等同于一个聊天模型。',['选择查询位置，观察能参与计算的 token。','打开因果掩码后，只允许访问当前位置及过去。','注意力权重由手工向量计算，不是语言模型给出的语义解释。'],'Attention(Q,K,V)=softmax(QKᵀ/√d + mask)V',[['query','查询位置',0,4,1,2],['causal','因果掩码',['开启','关闭'],'开启']],['预测下一个 token 时，能读取未来答案吗？',['不能，应屏蔽未来位置','可以，训练时知道就行'],0,'因果掩码防止未来信息泄漏；训练输入与目标还要正确错位。'],'https://arxiv.org/abs/1706.03762',{
file:'transformer',paper:'Attention Is All You Need',input:'离散 token 序列；翻译还需源序列与目标序列。',output:'每个位置的 token logits 或上下文表示。',objective:'教学代码用下一 token 交叉熵；原始翻译模型使用编码器—解码器及交叉注意力。',training:['对文本分词，构造输入与错位的目标。','加词嵌入和位置嵌入。','应用正确的注意力掩码，计算各位置 logits。','按有效目标位置计算交叉熵并更新。','用未参与训练的序列报告损失或任务指标。'],evaluation:'屏蔽 padding；避免训练/验证文本重叠。生成质量与训练损失要分开评估。',boundary:'代码仅训练 decoder-style 因果核心，省略原论文编码器—解码器翻译系统。浏览器用手工 Q/K 展示掩码。',reading:['先区分 self-attention 与 cross-attention。','沿编码器、解码器结构核对掩码的位置。','再看多头、位置编码、训练设置各自解决什么问题。']}),
lesson(32,'BERT','MASKED LANGUAGE MODEL',1,'看两边的上下文，补回被遮住的词。','BERT 的掩码语言建模用上下文预测被选中的 token。原始预训练还包含句子关系目标。',['选择一个被遮住的位置。','双向上下文可以查看它的左右两边。','损失只选取预测目标位置；这里不运行真实中文预测。'],'L_MLM=−Σᵢ∈M log p(xᵢ|corrupted x)',[['position','遮住的位置',0,4,1,2]],['本实验中的 MLM 损失计算在哪些位置？',['仅被选为预测目标的位置','所有输入位置都同等计入'],0,'MLM 通过选定目标位置计算损失；未选位置可以提供上下文。'],'https://arxiv.org/abs/1810.04805',{
file:'bert',paper:'BERT: Pre-training of Deep Bidirectional Transformers for Language Understanding',input:'被部分扰动的 token 序列与原始目标 token。',output:'掩码位置的词表概率；编码器表示可用于下游任务。',objective:'原始 BERT 使用 MLM 和 NSP；教学代码只实现全部替换为 MASK 的简化 MLM。',training:['从完整文本构造 token 与位置嵌入。','选择预测位置，保存原始 token。','扰动输入后，用双向编码器计算表示。','仅在目标位置优化词表交叉熵。','下游任务另加任务头，用独立数据评估。'],evaluation:'不要把简化 MLM 当作完整 BERT；真实预训练需要语料、分词器与多种扰动策略。',boundary:'手工 token 仅示意掩码位置。代码省略 NSP 与原论文 80/10/10 扰动配方，不加载 BERT 权重。',reading:['对比双向编码器与自回归语言模型。','查找 MLM 的样本构造和 NSP 的作用。','区分预训练目标、下游微调与评价任务。']}),
lesson(33,'GAN','GENERATIVE ADVERSARIAL NETWORK',2,'生成器与判别器，在对抗中学习分布。','生成器制造样本，判别器区分真实与生成数据。二者目标不同，通常交替更新。',['调节生成样本的均值，让它接近真实分布。','调节判别器阈值，观察真假两种损失。','这里的高斯样本和判别函数是简化模型。'],'L_D=−E log D(x)−E log(1−D(G(z))); L_G=−E log D(G(z))',[['mu','生成均值 μ',-2,3,.1,0],['threshold','判别阈值',-1,3,.1,1]],['更新判别器时，生成器应跟着一起更新吗？',['通常应断开生成器梯度','必须同时更新所有参数'],0,'判别器步骤通常对生成样本 detach；生成器步骤再优化生成器自己的目标。'],'https://arxiv.org/abs/1406.2661',{
file:'gan',paper:'Generative Adversarial Networks',input:'真实样本 x 与随机噪声 z，不要求每个噪声都有配对目标。',output:'生成器产生的样本。',objective:'判别器二分类；教学代码生成器采用非饱和 −log D(G(z))，与 minimax 写法区分。',training:['采样一批真实数据和噪声。','生成假样本并断开生成器梯度。','分别计算真假判别损失，更新判别器。','重新生成样本，经判别器计算生成器损失。','冻结判别器参数梯度，更新生成器，再检查样本多样性。'],evaluation:'不能仅凭一条损失判断生成质量；还需检查样本质量、多样性与训练稳定性。',boundary:'浏览器为一维高斯示意；代码学习一维分布，不是图像 GAN 或论文结果复现。',reading:['先明确两方分别优化什么，哪些参数被固定。','对比 minimax 与非饱和生成器目标。','再讨论模式坍塌与为什么损失低不代表样本一定更好。']}),
lesson(34,'DDPM','DENOISING DIFFUSION',2,'把数据逐渐加噪，再学习噪声是什么。','DDPM 定义前向加噪过程，并训练模型在不同噪声水平下预测噪声或相关目标。',['拖动信号保留系数 ᾱ，观察原信号与噪声混合。','同一组固定噪声让你能直接比较系数的影响。','训练学到的噪声预测器可用于逐步反向采样；此图只展示前向过程。'],'xₜ=√ᾱₜ x₀+√(1−ᾱₜ)ε; L_simple=E‖ε−εθ(xₜ,t)‖²',[['alpha','信号保留 ᾱ',.01,.99,.02,.7]],['训练噪声预测器时，目标噪声从哪里来？',['前向加噪时自己采样并保存','必须让人逐张标注'],0,'训练数据 x₀ 与采样噪声 ε 合成 xₜ，因此噪声目标已知。'],'https://arxiv.org/abs/2006.11239',{
file:'ddpm',paper:'Denoising Diffusion Probabilistic Models',input:'真实样本、采样时间步 t、标准高斯噪声 ε。',output:'噪声预测；完整生成还需要反向采样过程。',objective:'代码优化简化噪声预测 MSE；它对应具体参数化，不代表所有扩散模型都只用同一种目标。',training:['从真实数据或教学分布采样 x₀。','随机选择时间步 t 和噪声 ε。','按 ᾱₜ 合成 xₜ，并把 t 输入网络。','对预测噪声与 ε 计算 MSE，更新网络。','用正确的反向调度生成独立样本并评估分布。'],evaluation:'训练目标与生成采样分开检查；调度、步数和参数化不同会改变行为。',boundary:'代码在二维合成分布上训练噪声预测器，未实现完整反向采样，也不生成真实图像。',reading:['先画清前向 q 与反向 pθ 的方向。','核对时间步、αₜ、ᾱₜ 与噪声预测目标。','最后把训练损失与采样算法对应起来。']}),
lesson(35,'DQN','DEEP Q-NETWORK',3,'用神经网络估计动作价值。','DQN 将状态动作价值交给神经网络近似，并利用经验回放与目标网络构造训练信号。',['修改下一状态的目标 Q 值，观察 TD 目标。','真正终止时，下一状态价值被屏蔽。','目标网络参数用于构造目标，不在这一损失中反传。'],'y=r+γ(1−terminated)maxₐ′Q_target(s′,a′)',[['nextq','最大目标 Q',0,4,.1,2],['terminal','真正终止',['否','是'],'否']],['目标 Q 网络用于构造标签时，应反向传播吗？',['通常不应，应停止梯度','必须与在线网络一起反传'],0,'在线 Q 网络拟合停止梯度的 TD 目标；目标网络按独立规则更新。'],'https://arxiv.org/abs/1312.5602',{
file:'dqn',paper:'Playing Atari with Deep Reinforcement Learning；稳定化版本见后续 Nature DQN',input:'环境观察、离散动作、奖励、下一观察与终止标志。',output:'每个离散动作的 Q 值，以及据此选择的动作。',objective:'在线网络拟合停止梯度的 TD 目标。目标网络与回放用于稳定训练；2013 与后续 DQN 版本有差别。',training:['用 ε-greedy 与环境交互，存储转移。','从 replay 中抽取 batch，保留终止/截断区别。','用目标网络计算下一状态最大 Q，构造 TD 目标。','优化在线 Q 的回归损失，定期同步目标网络。','冻结网络、关闭探索，在多个独立回合评估。'],evaluation:'匹配环境步数、种子、评估回合；CartPole 的短运行只验证流程。',boundary:'浏览器为一次 TD 目标计算。代码调用 SB3 在 CartPole 训练，不是像素 Atari DQN 复现。',reading:['先把表格 Q-learning 的 Q 表替换成神经网络。','对照 2013 论文与后续目标网络、稳定化做法。','核对交互数据、回放采样和评估协议。']}),
lesson(36,'PPO','PROXIMAL POLICY OPTIMIZATION',3,'用剪切代理目标，控制更新的激励。','PPO 比较新旧策略对已采样动作的概率，用优势决定增加或减少该动作的倾向。',['拖动概率比 r 与优势 A，比较未剪切和剪切目标。','正、负优势的剪切行为不同，观察取最小值的位置。','clip 限制代理目标的激励，不保证每次实际策略变化都严格在 ε 内。'],'L_clip=min(rA, clip(r,1−ε,1+ε)A)',[['ratio','新旧概率比 r',.4,1.6,.02,1.2],['adv','优势 A',-1,1,.1,1],['epsilon','剪切 ε',.1,.3,.05,.2]],['PPO 的 clip 是否保证所有动作概率变化都不超过 ε？',['不保证，它剪切的是代理目标','保证所有概率都被硬限制'],0,'实际策略仍可变化；clip、KL 监控等各有不同作用。'],'https://arxiv.org/abs/1707.06347',{
file:'ppo',paper:'Proximal Policy Optimization Algorithms',input:'当前策略收集的 rollout、旧动作 log-prob、价值估计与奖励。',output:'更新后的策略与价值函数。',objective:'策略用剪切代理目标；实现还常包含价值损失和熵项。具体系数属于训练配置。',training:['用当前策略收集一段 rollout，保存旧 log-prob。','处理终止/截断，估计回报与优势。','计算新旧动作概率比，构造剪切目标。','在这批数据上做若干轮 minibatch 更新。','重新采集数据，并用冻结策略独立评估。'],evaluation:'旧 log-prob 应固定；不能随意把很久以前的 replay 数据直接用于常规 PPO。',boundary:'交互仅演示 clip 目标，未执行策略更新；代码调用 SB3 做短程 CartPole 训练。',reading:['先区分优势、概率比与策略参数。','分别画出正优势和负优势下的目标。','再读 rollout 到多轮更新的训练循环。']}),
lesson(37,'GCN','GRAPH CONVOLUTIONAL NETWORK',4,'把自己和邻居的特征混合。','GCN 结合图结构与节点特征。常见层用带自环的对称归一化邻接矩阵进行传播，再学习特征变换。',['四个节点构成链图，每个节点有一个标量特征。','加入自环后，按 D⁻½(A+I)D⁻½ 聚合。','多传播几层，比较特征逐渐混合的结果。'],'H′=σ(D̃⁻½(A+I)D̃⁻½HW)',[['layers','传播层数',1,4,1,1]],['加入自环后，聚合会包含自己的特征吗？',['会','不会，只看邻居'],0,'A+I 加入了自己到自己的连接。'],'https://arxiv.org/abs/1609.02907',{
file:'gcn',paper:'Semi-Supervised Classification with Graph Convolutional Networks',input:'邻接关系 A、节点特征 X、部分节点的标签与训练掩码。',output:'节点类别或节点表示。',objective:'只在训练标签掩码上计算交叉熵；图与特征的可用范围由评估设定决定。',training:['为图加入自环并计算对称归一化邻接矩阵。','传播邻域信息，线性变换后加入非线性。','堆叠输出层得到各节点 logits。','仅使用训练节点标签优化。','使用独立节点掩码报告指标，区分传导与归纳设定。'],evaluation:'训练时看到测试节点的特征与看到测试标签不同；必须说明设定。',boundary:'动画令 W=I 并省略非线性，只展示归一化聚合。代码为 6 节点教学图，不能代表大图性能。',reading:['先核对自环、度矩阵与归一化的顺序。','跟踪每层 H 的节点数与特征维度。','区分半监督标签掩码与整张图的结构可见性。']}),
lesson(38,'GAT','GRAPH ATTENTION NETWORK',4,'让邻居的贡献，通过注意力来分配。','GAT 在图允许的邻域里计算注意力，再加权聚合特征。它的归一化范围受图连接约束。',['拖动打分系数，比较三个邻居的贡献。','权重只在当前节点的合法邻域内归一化。','浏览器用简化分数，下载代码使用原始 GAT 风格的加性打分。'],'αᵢⱼ=softmaxⱼ(LeakyReLU(aᵀ[Whᵢ∥Whⱼ]))',[['sharp','邻居打分系数',-2,2,.1,1]],['图中不相连的节点会自动参与一跳聚合吗？',['不会，邻接掩码限定邻域','会，注意力默认连通所有节点'],0,'GAT 对图结构允许的邻居做注意力；自环需按设定加入。'],'https://arxiv.org/abs/1710.10903',{
file:'gat',paper:'Graph Attention Networks',input:'图边、节点特征与训练节点标签。',output:'注意力聚合后的节点表示或分类结果。',objective:'标签任务用监督损失，梯度同时学习投影与注意力打分参数。',training:['投影节点特征，构造合法边的成对特征。','用加性打分和 LeakyReLU 得到边分数。','对每个节点的邻域做 softmax。','加权聚合邻居，计算训练节点损失并更新。','固定图与掩码评估；多头设置要单独记录。'],evaluation:'注意力权重是模型内部量，不应直接等同于因果解释。',boundary:'浏览器只展示三个邻居的简化打分。代码为单头、小图、稠密实现，省略原论文多头与训练配方。',reading:['明确 softmax 是对哪些邻居求和。','对照特征投影、边打分、加权和三步。','再比较多头拼接与平均在不同层的作用。']}),
lesson(39,'LSTM','LONG SHORT-TERM MEMORY',5,'用门控，选择保留与写入的信息。','常用 LSTM 通过门控管理细胞状态。记忆不是完整保存所有过去，而是由训练得到的门控制。',['改变遗忘门 f，观察旧状态能保留多久。','改变输入门 i，观察新候选信息写入多少。','本图固定候选值和输出门，隔离两种门的作用。'],'cₜ=f·cₜ₋₁+i·g; hₜ=o·tanh(cₜ)',[['forget','遗忘门 f',0,1,.05,.8],['input','输入门 i',0,1,.05,.3]],['遗忘门接近 1，旧细胞状态通常怎样？',['保留更多','被更快清除'],0,'f 乘在旧细胞状态上；这里只观察门值作用，不保证任意真实序列都能长期记住。'],'https://doi.org/10.1162/neco.1997.9.8.1735',{
file:'lstm',paper:'Long Short-Term Memory；本课交互使用含遗忘门的常用后续变体',input:'按时间顺序的窗口 [B,T,F] 与未来目标。',output:'下一步预测或序列表示。',objective:'教学代码优化下一时刻数值的 MSE；其他任务可以使用不同输出头与损失。',training:['先按时间划分训练与验证，再用过去构造窗口。','依时间更新隐藏状态与细胞状态。','取最后有效状态，预测下一个值。','对预测误差做反向传播并更新。','在更晚时间段上验证，避免窗口跨越数据边界。'],evaluation:'随机打散后切分高度重叠窗口可能泄漏未来；真实评估需时间切分和基线。',boundary:'1997 原始论文与现代含遗忘门实现有历史差别。代码用 PyTorch 常见 LSTM，在合成正弦窗口训练。',reading:['先区分细胞状态 c 与隐藏状态 h。','对照原始结构与后续遗忘门变体。','追踪一个时间步的门、状态与输出形状。']}),
lesson(40,'TCN','TEMPORAL CONVOLUTIONAL NETWORK',5,'用因果与膨胀卷积，扩展过去的视野。','TCN 用时间卷积处理序列。因果性防止读取未来，膨胀卷积让有限层数覆盖更远的历史。',['卷积核大小固定为 3，膨胀率按层取 1、b、b²。','改变层数与膨胀基数，观察可感受的过去范围。','图中最多画最近 24 步；超出窗口的感受野仍在数值中显示。'],'R=1+(k−1)Σₗdₗ; 此处每层一个卷积，k=3',[['layers','卷积层数',1,4,1,3],['base','膨胀基数',1,3,1,2]],['预测 t 时刻时，因果卷积能看 t+1 吗？',['不能','能，膨胀率大就能'],0,'膨胀扩大过去的覆盖范围，因果掩码或左填充仍限制未来信息。'],'https://arxiv.org/abs/1803.01271',{
file:'tcn',paper:'An Empirical Evaluation of Generic Convolutional and Recurrent Networks for Sequence Modeling',input:'按时间排列的多通道序列；代码使用过去窗口。',output:'序列输出或下一步数值预测。',objective:'代码用 MSE 拟合合成序列的下一步。',training:['先划分时间段，构建只含过去的窗口。','每层只做左侧填充，使用膨胀时间卷积。','经非线性或残差块组合历史表示。','预测未来目标，计算损失并优化。','在后续时间段比较简单基线及不同感受野。'],evaluation:'不能仅凭卷积输出长度判断因果性；修改未来输入应不影响过去输出。',boundary:'动画按每层一个卷积计算感受野；论文残差块可能含多个卷积。代码为小型因果膨胀栈，省略完整 TCN 配方。',reading:['先在时间轴上展开一个膨胀卷积。','数清每个残差块的卷积数，再算感受野。','阅读对比实验时核对序列任务、预算和模型设置。']}),
lesson(41,'CTC','CONNECTIONIST TEMPORAL CLASSIFICATION',6,'没有逐帧对齐标签，也能训练序列识别。','CTC 对能折叠成目标文本的对齐路径求和。它适合输入帧多于输出符号、对齐未知的任务。',['选择一条帧级路径。','先合并连续重复符号，再移除 blank。','blank 分开的重复字母不能直接合并。'],'p(y|x)=Σπ:B(π)=y ∏ₜp(πₜ|x); L=−log p(y|x)',[['path','对齐路径',['A A _ B B _','A _ A B B _','_ A A _ B B'],'A A _ B B _']],['路径 A _ A 折叠成什么？',['A','AA'],1,'两个 A 被 blank 隔开，不是连续重复；移除 blank 后得到 AA。'],'https://www.cs.toronto.edu/~graves/icml_2006.pdf',{
file:'ctc',paper:'Connectionist Temporal Classification: Labelling Unsegmented Sequence Data with Recurrent Neural Networks',input:'输入帧序列、每条输入长度、未对齐目标符号与目标长度。',output:'每帧含 blank 的符号概率；经解码得到文本。',objective:'CTC 对所有合法对齐路径求和后取负对数，而不是只使用一条贪心路径。',training:['将音频或时序输入编码成帧级表示。','输出含 blank 的帧级 logits，转成 log-prob。','传入真实输入/目标长度，计算 CTC 损失。','反向传播更新编码器与输出头。','解码后计算字符/词错误率，另检查对齐约束。'],evaluation:'本课的折叠动画不是完整 CTC 动态规划，也不等于 beam search 解码。',boundary:'代码用合成帧特征与短符号目标运行 CTCLoss，不识别真实语音，也未训练完整声学系统。',reading:['先掌握 blank 与重复折叠的顺序。','枚举小例子的所有合法对齐，再理解路径求和。','最后区分训练目标、贪心折叠与搜索解码。']}),
lesson(42,'wav2vec 2.0','MASKED SPEECH REPRESENTATION',6,'遮住语音表示，靠上下文寻找目标。','wav2vec 2.0 从未标注音频学习表示，结合掩码上下文、量化目标与对比学习，再可用标注语音微调。',['对比一个正目标和两个负候选的相似度。','调节温度，观察候选概率与对比损失。','本图向量为手工示例；没有真实语音输入。'],'L_contrastive=−log[exp(sim(c,q⁺)/τ)/Σq exp(sim(c,q)/τ)]',[['temperature','温度 τ',.1,1,.1,.5]],['预训练对比目标是否必须来自人工文字转写？',['不必，可以来自音频自身的表征','必须，每帧都需要文字标签'],0,'自监督预训练利用音频本身构造目标；下游识别微调可再使用转写标签。'],'https://arxiv.org/abs/2006.11477',{
file:'wav2vec2_core',paper:'wav2vec 2.0: A Framework for Self-Supervised Learning of Speech Representations',input:'未标注音频；代码用合成序列特征演示掩码对比核心。',output:'上下文语音表示；识别任务可接 CTC 输出头。',objective:'原方法包含量化目标、对比项与多样性约束；代码仅实现掩码对比损失。',training:['从音频经特征编码器得到潜在序列。','遮住部分潜在位置，用上下文网络生成表示。','构造量化正目标与负候选。','优化对比项及相关量化约束。','需要识别时，再用带转写的数据微调并测 WER。'],evaluation:'预训练表征损失与识别 WER 不同；比较时区分未标注和有标注数据量。',boundary:'浏览器使用手工向量；代码仅运行掩码对比核心，省略音频卷积前端、可学习量化器、多样性损失和 CTC 微调。',reading:['画出特征编码器、上下文网络和量化目标三条信息流。','确认掩码施加位置与正负目标来源。','把无转写预训练与有转写微调分开阅读。']})
];
